import os,re,sys
root=".agents/instructions"
# collect files
files=[]
for dirpath,dirs,filenames in os.walk(root):
    for fn in filenames:
        if fn.endswith('.instructions.md'):
            files.append(os.path.join(dirpath,fn))
files.sort()
print(f"files_count={len(files)}")
# descriptions
bad_desc=[]
for f in files:
    text=open(f,encoding='utf-8').read()
    m=re.search(r'^description:\s*"([^"]*)"', text, re.M)
    desc=m.group(1) if m else ''
    if not (desc.startswith('Use when') or desc.startswith('Use at the start of and throughout every session')):
        bad_desc.append((f,desc))
if not bad_desc:
    print('DESCRIPTION_CHECK: OK')
else:
    print('DESCRIPTION_CHECK: FAIL')
    for f,d in bad_desc:
        print('BAD_DESC:',f,'->',d)
# applyTo
applyto=[]
for f in files:
    text=open(f,encoding='utf-8').read()
    if 'applyTo' in text:
        applyto.append(f)
if not applyto:
    print('APPLYTO_CHECK: OK (none found)')
else:
    print('APPLYTO_CHECK: FAIL')
    for f in applyto: print('FOUND applyTo in',f)
# Links in three files
three=[
'.agents/instructions/ticket/workflow.instructions.md',
'.agents/instructions/commit/generated-files.instructions.md',
'.agents/instructions/orchestration/session-artifacts.instructions.md'
]
link_re=re.compile(r'\[.*?\]\(([^)]+)\)')
all_bad=0
for f in three:
    print('--',f,'--')
    text=open(f,encoding='utf-8').read()
    for link in link_re.findall(text):
        if link.startswith('http') or link.startswith('mailto:') or link.startswith('#'):
            print('SKIP',link)
            continue
        target=os.path.normpath(os.path.join(os.path.dirname(f), link))
        exists=os.path.exists(target)
        print(('OK' if exists else 'BROKEN')+':',link,'->',target)
        if not exists: all_bad+=1
print('LINKS_THREE_FILES:', 'OK' if all_bad==0 else f'FAIL ({all_bad} broken)')
# Workspace-wide link check (report only broken)
broken=[]
for f in files:
    text=open(f,encoding='utf-8').read()
    for link in link_re.findall(text):
        if link.startswith('http') or link.startswith('mailto:') or link.startswith('#'):
            continue
        target=os.path.normpath(os.path.join(os.path.dirname(f), link))
        if not os.path.exists(target):
            broken.append((f,link,target))
if not broken:
    print('WORKSPACE_WIDE_LINK_CHECK: OK')
else:
    print('WORKSPACE_WIDE_LINK_CHECK: FAIL')
    for f,l,t in broken:
        print('BROKEN:',f,'->',l,'->',t)
# Edited files by me (the three changed)
print('EDITED_FILES_BY_ME:')
for f in three:
    print(f)
PY
